CREATE TABLE users(id TEXT PRIMARY KEY,phone TEXT UNIQUE NOT NULL,enabled INTEGER DEFAULT 0,autosave INTEGER DEFAULT 0,envelope TEXT,consent TEXT,created INTEGER NOT NULL);
CREATE TABLE sessions(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE codes(phone TEXT NOT NULL,purpose TEXT NOT NULL,hash TEXT NOT NULL,expires INTEGER NOT NULL,attempts INTEGER DEFAULT 0,PRIMARY KEY(phone,purpose));
CREATE TABLE sends(phone TEXT,ip TEXT,time INTEGER);
CREATE TABLE nodes(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,parent TEXT,kind TEXT NOT NULL,meta TEXT NOT NULL,version INTEGER DEFAULT 0,deleted INTEGER DEFAULT 0,updated INTEGER NOT NULL);
CREATE TABLE versions(id TEXT PRIMARY KEY,node_id TEXT NOT NULL,user_id TEXT NOT NULL,version INTEGER NOT NULL,blob TEXT NOT NULL,bytes INTEGER NOT NULL,created INTEGER NOT NULL,UNIQUE(node_id,version));
CREATE TABLE uploads(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,node_id TEXT NOT NULL,expected INTEGER NOT NULL,total INTEGER NOT NULL,received INTEGER DEFAULT 0,created INTEGER NOT NULL);
CREATE TABLE publications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,node_id TEXT,kind TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,cover TEXT,category TEXT,blob TEXT NOT NULL,bytes INTEGER NOT NULL,text TEXT,status TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE audit(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT,action TEXT,time INTEGER,detail TEXT);
